tool_input_args.value:
cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// 1. Check the customer exists
const customer = db.prepare(\"SELECT * FROM users WHERE user_id = 'shop_001'\").get();
if (!customer) { console.log('ERROR: Customer shop_001 not found'); process.exit(1); }
console.log('Customer:', customer.name, '| Tier:', customer.loyalty_tier);

// 2. Check the cart exists
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = 'shop_001'\").get();
if (!cart) { console.log('ERROR: No cart for shop_001'); process.exit(1); }
console.log('Cart ID:', cart.cart_id);
console.log('Current items:', cart.item_ids_json);

// 3. Check existing cart items
const existingItems = db.prepare(\"SELECT * FROM cart_items WHERE customer_id = 'shop_001'\").all();
console.log('Existing cart_items count:', existingItems.length);
for (const ci of existingItems) {
  console.log('  -', ci.cart_item_id, ci.product_id, 'qty:', ci.quantity);
}

// 4. Determine next cart_item_id
let maxSeq = 0;
const allItems = db.prepare('SELECT cart_item_id FROM cart_items').all();
for (const row of allItems) {
  const m = row.cart_item_id.match(/^CI-(\d+)$/);
  if (m) maxSeq = Math.max(maxSeq, parseInt(m[1]));
}
const nextId = 'CI-' + String(maxSeq + 1).padStart(4, '0');
console.log('Next cart_item_id:', nextId);

// 5. Check if PROD-FA0948 is already in the cart for this customer
const alreadyInCart = existingItems.find(ci => ci.product_id === 'PROD-FA0948');
if (alreadyInCart) {
  console.log('NOTE: Product already in cart as', alreadyInCart.cart_item_id, 'qty:', alreadyInCart.quantity);
}
"

