cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Search by exact email
let user = db.prepare(\"SELECT * FROM users WHERE email = 'user@example.com'\").get();
if (!user) {
  // Try a fuzzy search
  const results = db.prepare(\"SELECT user_id, name, email, loyalty_tier, skill_ids_json FROM users WHERE email LIKE '%user@example%' OR email LIKE '%user%example%'\").all();
  console.log('No exact match for user@example.com');
  console.log('Fuzzy results:', JSON.stringify(results, null, 2));
} else {
  console.log('Found:', JSON.stringify(user, null, 2));
}
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Search by name (exact and fuzzy)
const exact = db.prepare(\"SELECT user_id, name, email, loyalty_tier, skill_ids_json FROM users WHERE name = 'Alex Johnson'\").all();
console.log('Exact match:', JSON.stringify(exact, null, 2));

const fuzzy = db.prepare(\"SELECT user_id, name, email, loyalty_tier, skill_ids_json FROM users WHERE name LIKE '%Alex%' OR name LIKE '%Johnson%'\").all();
console.log('Fuzzy match:', JSON.stringify(fuzzy, null, 2));
"

